#pragma once

#include <cstddef>
#include <cstdint>

#include "EpdFontData.h"

/// Parsed view over a CPFN font pack.  The pack is generated by
/// tools/generate_font_pack.cpp from the built-in CJK faces that used to be
/// linked into the firmware.  This class does not own the bytes: the caller
/// keeps the buffer alive (the device loader keeps a PSRAM allocation for the
/// whole session).
class ExternalFontPack {
 public:
  static constexpr size_t kMaxFonts = 4;
  static constexpr size_t kNameLen = 12;
  static constexpr size_t kEntrySize = 48;
  static constexpr size_t kHeaderSize = 16;

  /// Validate and index a pack.  Returns false on bad magic/version, an
  /// out-of-range offset, a misaligned array, or a CRC mismatch.  On failure
  /// the object is left empty; it never points at unvalidated bytes.
  bool parse(const uint8_t* data, size_t size);

  /// nullptr when the pack has no such face.
  const EpdFontData* get(const char* name) const;

  size_t fontCount() const { return count_; }
  const uint8_t* data() const { return data_; }
  size_t size() const { return size_; }

 private:
  const uint8_t* data_ = nullptr;
  size_t size_ = 0;
  uint8_t count_ = 0;
  EpdFontData fonts_[kMaxFonts]{};
  char names_[kMaxFonts][kNameLen]{};
};
